#include <iostream>
using namespace std;

int main() {
    int left = 47;
    int sum = 0;
    while (left > 0) {
        sum += left % 10;
        left /= 10;
    }
    cout << "Digit sum: " << sum << endl;
    return 0;
}

int n = 123;
int reversed = 0;
while (n > 0) {
    reversed = reversed * 10 + n % 10;
    n /= 10;
}
